/*	name:	Residuals.c	type:	C	Programmers:AGR	Arthur RymanChange History:1991/10/29 AGR V100	Used sqrt(extended) for C++.1991/11/30 AGR V200	Upgraded to C++.AGR	V201	1994/11/20	Minimize includes.AGR	V202	1995/08/05	Port to Symantec C++.*/#include <math.h>	// V202 sqrt#ifndef SPLINE_DEFINES_H#include ":src:spline:defines.h"	// CT_BEZIER#endif#ifndef SPLINE_SPLPROTO_H#include ":src:spline:splproto.h"	// Residuals#endif#ifndef SPLINE_SYNTAX_H#include ":src:spline:syntax.h"	// FOR#endif#define Bases(i,j) (bases[ (i)*ndata + (j) ])float Residuals(int typeCurve, float *uInd, Point *data, float *xcoef,	float *ycoef, float *knots, float *bases, int ndata, int ncv){    int     i, j, seg, idx;    float   xx, yy, residuals;    /* double  sqrt();	V100 */    IF typeCurve == CT_BEZIER THEN        xx = xcoef[0] - data[0].h;        yy = ycoef[0] - data[0].v;        residuals = sqrt( (extended) (xx*xx + yy*yy) );        FOR j=1; j<ndata; j++ DO            xx = yy = 0.0;            FOR i=0; i<ncv; i++ DO                xx += xcoef[i] * (Bases(i,j));                yy += ycoef[i] * (Bases(i,j));            E_FOR;			xx -= data[j].h;			yy -= data[j].v;            residuals += sqrt( (extended) (xx*xx + yy*yy) );        E_FOR;    ELIF ( typeCurve == CT_IBSPLINE ) ||         ( typeCurve == CT_PBSPLINE ) ||         ( typeCurve == CT_FBSPLINE ) THEN        seg = 3;        idx = 0;        residuals = 0;        WHILE idx<ndata DO			xx =   xcoef[seg-3]*Bases(seg-3,idx)				 + xcoef[seg-2]*Bases(seg-2,idx)				 + xcoef[seg-1]*Bases(seg-1,idx)				 + xcoef[seg  ]*Bases(seg  ,idx);            yy =   ycoef[seg-3]*Bases(seg-3,idx)				 + ycoef[seg-2]*Bases(seg-2,idx)				 + ycoef[seg-1]*Bases(seg-1,idx)				 + ycoef[seg  ]*Bases(seg  ,idx);			xx -= data[idx].h;			yy -= data[idx].v;            residuals += sqrt( (extended) (xx*xx + yy*yy) );            idx++;			WHILE uInd[idx] > knots[seg+1] DO seg++; E_WHILE;			IF seg >= ncv THEN				/* fprintf( outFile, "seg too large in Residuals, seg = %d, idx = %d, ndata = %d\n",						 seg, idx, ndata );*/	/* V401 JS 88/07/28 */				return( residuals );			FI;        E_WHILE;    FI;     /* fprintf( outFile, "Sum square of residuals = %f\n", residuals );*/	/* V401 JS 88/07/28 */    return( residuals );}